<?php
require dirname(__DIR__).'/app/bootstrap.php';
$rows=[];$error='';$page=max(1,min(100000,(int)($_GET['page']??1)));
try{$q=db()->prepare('SELECT id,tested_at,download,upload,ping,jitter,server_name,connection_mode FROM results WHERE owner_hash=? ORDER BY tested_at DESC LIMIT 21 OFFSET '.(($page-1)*20));$q->execute([ownerHash()]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$error='Riwayat belum dapat dimuat. Coba lagi nanti.';}
$more=count($rows)>20;$rows=array_slice($rows,0,20);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riwayat Saya · Speedtest HST</title><link rel="stylesheet" href="/style.css"></head><body><header><a class="brand" href="/"><img src="/logo.png" alt="Lambang HST"><span>SPEEDTEST HST<strong>Riwayat Saya</strong></span></a><a href="/">← Uji Kecepatan</a></header><main><div class="eyebrow">PENGUJIAN ANDA</div><h1>Setiap tes,<br><em>tercatat di sini.</em></h1><p class="intro">Riwayat pengujian dari browser ini. Buka hasil untuk melihat detail dan membagikan tautannya.<br>Menghapus cookie atau berganti browser akan memutus akses ke daftar ini.</p><p role="alert"><?=h($error)?></p><div class="table-wrap"><table><thead><tr><th>Waktu (WITA)</th><th>Download</th><th>Upload</th><th>Ping</th><th>Server / Koneksi</th><th>Hasil</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h((new DateTimeImmutable($r['tested_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Makassar'))->format('d M Y H:i'))?></td><td><?=h($r['download'])?> Mbps</td><td><?=h($r['upload'])?> Mbps</td><td><?=h($r['ping'])?> ms</td><td><?=h($r['server_name']??'Server sebelumnya')?> · <?=h(ucfirst($r['connection_mode']??'multi'))?></td><td><a class="mint" href="/result/<?=h($r['id'])?>">Lihat detail ↗</a></td></tr><?php endforeach?><?php if(!$rows&&!$error):?><tr><td colspan="6">Belum ada riwayat di browser ini. <a class="mint" href="/">Mulai tes pertama Anda →</a></td></tr><?php endif?></tbody></table></div><div class="pager"><span>Halaman <?=$page?></span><span><?php if($page>1):?><a href="?page=<?=$page-1?>">← Sebelumnya</a> · <?php endif?><?php if($more):?><a href="?page=<?=$page+1?>">Berikutnya →</a><?php endif?></span></div></main></body></html>
